package android.os;import java.util.*;
public class Parcel {List<Object> data=new ArrayList<>();int i;public static Parcel obtain(){return new Parcel();}public void recycle(){}public void writeInterfaceToken(String s){data.add(s);}public void enforceInterface(String s){if(!s.equals(data.get(i++)))throw new SecurityException();}public void writeStrongBinder(IBinder b){data.add(b);}public IBinder readStrongBinder(){return (IBinder)data.get(i++);}public void writeInt(int n){data.add(n);}public int readInt(){return (Integer)data.get(i++);}public void writeLong(long n){data.add(n);}public long readLong(){return (Long)data.get(i++);}public void writeBundle(Bundle b){data.add(b);}public Bundle readBundle(ClassLoader c){return (Bundle)data.get(i++);}public void writeNoException(){}public void readException(){}}
